sqlEquivalent:
CREATE TABLE lab_learners (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL);
CREATE TABLE lab_classes (id SERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL);
CREATE TABLE lab_class_enrollments (
  learner_id INTEGER NOT NULL REFERENCES lab_learners(id) ON DELETE CASCADE,
  class_id INTEGER NOT NULL REFERENCES lab_classes(id) ON DELETE CASCADE,
  grade VARCHAR(2),
  PRIMARY KEY (learner_id, class_id)
);

starterCode:
// JavaScript track — same Prisma DSL
model LabLearner {
  id Int @id @default(autoincrement())
  name String
  enrollments LabClassEnrollment[]
  @@map("lab_learners")
}
model LabClass {
  id Int @id @default(autoincrement())
  title String
  enrollments LabClassEnrollment[]
  @@map("lab_classes")
}
model LabClassEnrollment {
  learnerId Int @map("learner_id")
  classId Int @map("class_id")
  grade String?
  learner LabLearner @relation(fields: [learnerId], references: [id], onDelete: Cascade)
  class LabClass @relation(fields: [classId], references: [id], onDelete: Cascade)
  @@id([learnerId, classId])
  @@map("lab_class_enrollments")
}

